B.Y7=new A.y(B.a1A,["\u092a\u0940\u091c\u093c\u094b\u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 \u0938\u0947! \u0935\u094b\u0932\u094d\u091f\u0947\u091c \u092e\u093f\u0932\u0928\u0947 \u092a\u0930 \u0915\u094d\u0930\u093f\u0938\u094d\u091f\u0932 \u092e\u0941\u0921\u093c\u0924\u093e \u0939\u0948 \u0914\u0930 \u0924\u0947\u091c\u093c\u0940 \u0938\u0947 \u0915\u0902\u092a\u0928 \u0915\u0930\u0915\u0947 \u0927\u094d\u0935\u0928\u093f \u092a\u0948\u0926\u093e \u0915\u0930\u0924\u093e \u0939\u0948\u0964","\u090f\u0915\u094d\u091f\u093f\u0935 \u092c\u091c\u093c\u0930 5V \u0926\u0947\u0924\u0947 \u0939\u0940 \u0938\u094d\u0925\u093f\u0930 \u092c\u0940\u092a \u0915\u0930\u0924\u093e \u0939\u0948\u0964 \u092a\u0948\u0938\u093f\u0935 \u092c\u091c\u093c\u0930 \u0915\u094b \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u092b\u094d\u0930\u0940\u0915\u094d\u0935\u0947\u0902\u0938\u0940 \u0926\u0947\u0915\u0930 \u0938\u0902\u0917\u0940\u0924 \u092c\u091c\u093e\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964","\u092f\u0939 \u092a\u093f\u0928 \u092a\u0930 \u0938\u0947\u0915\u0902\u0921 \u092e\u0947\u0902 880 \u092c\u093e\u0930 \u0935\u094b\u0932\u094d\u091f\u0947\u091c \u092c\u0926\u0932\u0924\u093e \u0939\u0948, \u091c\u093f\u0938\u0938\u0947 880 Hz \u0915\u0940 \u092c\u0940\u092a \u0938\u0941\u0928\u093e\u0908 \u0926\u0947\u0924\u0940 \u0939\u0948\u0964","\u0939\u093e\u0901! \u092a\u0948\u0938\u093f\u0935 \u092c\u091c\u093c\u0930 \u092e\u0947\u0902 \u0905\u0932\u0917-\u0905\u0932\u0917 \u092b\u094d\u0930\u0940\u0915\u094d\u0935\u0947\u0902\u0938\u0940 (\u0938\u093e, \u0930\u0947, \u0917, \u092e) \u0926\u0947\u0915\u0930 \u092e\u093e\u0930\u093f\u092f\u094b \u092f\u093e \u0938\u094d\u091f\u093e\u0930 \u0935\u093e\u0930\u094d\u0938 \u0927\u0941\u0928 \u092c\u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"],t.w)
B.Yx=new A.y(B.ae,["\u092c\u091c\u093c\u0930 (Buzzer - \u092a\u0940\u091c\u093c\u094b \u0938\u093e\u0909\u0902\u0921\u0930)","\u092a\u0940\u091c\u093c\u094b \u092c\u091c\u093c\u0930 \u0915\u0902\u092a\u0928 \u0915\u0930\u0915\u0947 \u0906\u0935\u093e\u091c\u093c \u0914\u0930 \u0905\u0932\u093e\u0930\u094d\u092e \u0915\u0948\u0938\u0947 \u0928\u093f\u0915\u093e\u0932\u0924\u093e \u0939\u0948?","\u092c\u091c\u093c\u0930 \u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u0924\u0930\u0902\u0917\u094b\u0902 \u0915\u094b \u0927\u094d\u0935\u0928\u093f \u0924\u0930\u0902\u0917\u094b\u0902 \u092e\u0947\u0902 \u092c\u0926\u0932\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0915\u0947 \u0905\u0902\u0926\u0930 \u090f\u0915 \u092a\u0940\u091c\u093c\u094b-\u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u093f\u0915 \u0938\u093f\u0930\u0947\u092e\u093f\u0915 \u0921\u093f\u0938\u094d\u0915 \u0939\u094b\u0924\u0940 \u0939\u0948 \u091c\u094b \u0915\u0930\u0902\u091f \u092e\u093f\u0932\u0928\u0947 \u092a\u0930 \u0924\u0947\u091c\u093c\u0940 \u0938\u0947 \u0915\u0902\u092a\u0928 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964 \u0906\u0935\u0943\u0924\u094d\u0924\u093f (Hz) \u092c\u0926\u0932\u0915\u0930 \u0906\u0935\u093e\u091c\u093c \u0915\u0940 \u092a\u093f\u091a \u092c\u0926\u0932\u0940 \u091c\u093e \u0938\u0915\u0924\u0940 \u0939\u0948\u0964","\u092f\u093e\u0926 \u0930\u0916\u0928\u0947 \u0915\u093e \u0909\u0926\u093e\u0939\u0930\u0923: \u0926\u0930\u092c\u093e\u0928 \u0915\u0941\u0924\u094d\u0924\u0947 \u0915\u0940 \u0918\u0902\u091f\u0940 \u092f\u093e \u091d\u0940\u0902\u0917\u0941\u0930 \u091c\u0948\u0938\u093e! \u0915\u0930\u0902\u091f \u092e\u093f\u0932\u0928\u0947 \u092a\u0930 \u092f\u0939 \u090f\u0915 \u0938\u0947\u0915\u0902\u0921 \u092e\u0947\u0902 \u0938\u0948\u0915\u0921\u093c\u094b\u0902 \u092c\u093e\u0930 \u0915\u0902\u092a\u0928 \u0915\u0930\u0915\u0947 \u0915\u092e\u0930\u0947 \u092e\u0947\u0902 \u0906\u0935\u093e\u091c\u093c \u0917\u0942\u0902\u091c\u093e \u0926\u0947\u0924\u093e \u0939\u0948\u0964","\u0915\u093e\u0930\u0923 \u0914\u0930 \u092a\u094d\u0930\u092d\u093e\u0935: \u092c\u091c\u093c\u0930 \u0915\u0940 \u0906\u0935\u093e\u091c\u093c 360 \u0921\u093f\u0917\u094d\u0930\u0940 \u092e\u0947\u0902 \u092b\u0948\u0932\u0924\u0940 \u0939\u0948\u0964 \u092f\u0926\u093f \u0907\u0902\u0938\u093e\u0928 \u0930\u094b\u092c\u094b\u091f \u0915\u094b \u0928\u0939\u0940\u0902 \u0926\u0947\u0916 \u0930\u0939\u093e, \u0924\u092c \u092d\u0940 \u0916\u0924\u0930\u0947 \u0915\u093e \u0938\u093e\u092f\u0930\u0928 \u0924\u0941\u0930\u0902\u0924 \u0938\u0941\u0928\u093e\u0908 \u0926\u0947 \u091c\u093e\u0924\u093e \u0939\u0948\u0964","\u0905\u0938\u0932\u0940 \u0926\u0941\u0928\u093f\u092f\u093e \u092e\u0947\u0902: \u092e\u093e\u0907\u0915\u094d\u0930\u094b\u0935\u0947\u0935 \u091f\u093e\u0907\u092e\u0930, \u0915\u093e\u0930 \u0930\u093f\u0935\u0930\u094d\u0938 \u092a\u093e\u0930\u094d\u0915\u093f\u0902\u0917 \u0938\u0947\u0902\u0938\u0930, \u0938\u094d\u092e\u094b\u0915 \u0905\u0932\u093e\u0930\u094d\u092e \u0914\u0930 \u0921\u093f\u091c\u093f\u091f\u0932 \u0918\u0921\u093c\u0940\u0964","\u0915\u092c \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930\u0947\u0902: \u091c\u092c \u0930\u094b\u092c\u094b\u091f \u0915\u094b \u0926\u0940\u0935\u093e\u0930 \u0938\u0947 \u091f\u0915\u094d\u0915\u0930 \u0915\u093e \u0916\u0924\u0930\u093e \u0939\u094b (\u0926\u0942\u0930\u0940 < 10 \u0938\u0947\u092e\u0940) \u092f\u093e \u0905\u0932\u093e\u0930\u094d\u092e \u092c\u091c\u093e\u0928\u093e \u0939\u094b\u0964",B.Vs,B.Sb,B.Y7],t.R)
